    console.timeEnd('[CoreKit] loginWithJWT');
    logger.debug('[CoreKit] loginWithJWT completed, status:', coreKit.status);
  } catch (err) {
    console.timeEnd('[CoreKit] loginWithJWT');
    logger.error('[CoreKit] loginWithJWT FAILED:', err);
    throw err;
  }

