1	//! The production rotation seams: the owner arm of the two impure edges the
2	//! read-plane rotation primitives run on (blueprint/engine.md "Rotation
3	//! primitives", "Pointer planes"; #1014).
4	//!
5	//! [`crate::rotation`] is pure apart from a gated read of a descendant scope
6	//! root's own write-body index ([`ChildIndexResolver`]) and a register-first CAS
7	//! publish of a re-sealed scope root ([`ScopeRootPublisher`]). Both land here,
8	//! composed from the net plane already in place — fan-out GET plus
9	//! [`RootAdopter`] for the read, [`author`](super::author) plus
10	//! [`publish_record`] for the write. No crypto and no trust logic is added: the
11	//! adoption gate stays the only judge of a resolved record, and the publish
12	//! pipeline stays the only path to the transport.
13	
14	use core::cell::RefCell;
15	use std::collections::BTreeMap;
16	
17	use cipherbox_core::ipns::IpnsName;
18	use cipherbox_core::kdf;
19	use cipherbox_core::seal::{
20	    AadContext, ChildScopeRef, Envelope, GrantSection, ReadBody, STRUCT_TAG_OWNER_BLOB,
21	    STRUCT_TAG_WRITE_BODY, WriteBody, decode_write_body, open_owner_blob, unseal, verify_grant_set,
22	};
23	use cipherbox_core::suite::ecdsa::{EcdsaSignature, EcdsaVerifier};
24	use cipherbox_core::suite::secret::SECRET_LEN;
25	use cipherbox_core::suite::x25519::X25519Secret;
26	use zeroize::Zeroizing;
27	
28	use super::adopter::RootAdopter;
29	use super::author::{ENVELOPE_V, EnvelopeAuthoring, author_scope_root_with_section};
30	use super::publish::PublishOutcome;
31	use super::record_publish::{HeadBinding, RecordPublishRequest, preflight, publish_record};
32	use crate::api::ApiClient;
33	use crate::content::Gateway;
34	use crate::entropy::Entropy;
35	use crate::gate::{GateError, floor};
36	use crate::net::fanout_get_verify;
37	use crate::profile::SyncTimingProfile;
38	use crate::rotation::{
39	    ChildIndexResolver, ResealedScopeRoot, ResolveFailure, ScopeRootPublishError,
40	    ScopeRootPublisher,
41	};
42	use crate::seams::{CredentialStore, FloorStore, Http, RecordTransport, Scheduler};
43	use crate::session::SessionIdentity;
44	
45	/// The owner key material both rotation edges run under. The owner is the
46	/// terminal owner of its own key material, so nothing here is zeroized.
47	pub struct OwnerRotationKeys<'a> {
48	    /// Opens each scope root's owner blob — the owner's read-seed source, and
49	    /// the key the re-sealed section must reopen under before it is signed.
50	    pub enc_secret: &'a X25519Secret,
51	    /// The contact-anchored owner identity: the adoption gate's stage-2 anchor.
52	    pub identity: &'a EcdsaVerifier,
53	}
54	
55	/// The owner-arm rotation seams over the live net plane.
56	pub struct OwnerRotationNet<'a, T, H: Http, C: CredentialStore, F, Sch, E> {
57	    /// The record-plane transport: fan-out GET for the read, CAS PUT for the
58	    /// publish.
59	    pub transport: &'a T,
60	    /// The API client: register-first and the head-block upload.
61	    pub api: &'a ApiClient<H, C>,
62	    /// Content read sources for the head block.
63	    pub gateway: &'a Gateway,
64	    /// The HTTP seam the content fetch rides.
65	    pub http: &'a H,
66	    /// The durable floors the adoption gate reads and advances.
67	    pub floors: &'a F,
68	    /// The scheduler the publish pipeline's background re-PUT rides.
69	    pub scheduler: &'a Sch,
70	    /// The publish pipeline's timing policy.
71	    pub profile: &'a SyncTimingProfile,
72	    /// Injected entropy — the per-seal nonce source (determinism law: engine
73	    /// logic never reaches for an RNG).
74	    pub entropy: &'a RefCell<E>,
75	    /// The owner material.
76	    pub keys: OwnerRotationKeys<'a>,
77	    /// The ancestor seeds every interior scope root's gated read needs.
78	    pub ancestry: RotationAncestry,
79	}
80	
81	/// The `scope_id -> parent` edges and per-scope override seeds a walk needs to
82	/// derive each interior scope root's ancestor node seed.
83	///
84	/// Every interior scope root carries an ascent link, and the adoption gate
85	/// derives the expected ascent keypair from the **reader's** ancestor node seed
86	/// rather than from the record — no seed, no gate pass. Seeded at the rotating
87	/// root ([`Self::rooted_at`]) and extended as the walk gates each level: a
88	/// descendant's parent edge comes from the gated parent index that named it, and
89	/// the parent's override seed from that parent's own gate-passing owner blob, so
90	/// no network-supplied field ever chooses which seed a scope is read under.
91	#[derive(Default)]
92	pub struct RotationAncestry {
93	    inner: RefCell<Ancestry>,
94	}
95	
96	#[derive(Default)]
97	struct Ancestry {
98	    /// The rotating root's own ancestor node seed, when it is itself an interior
99	    /// scope root ([`RotationAncestry::under_parent_node_seed`]).
100	    root: Option<([u8; 16], Zeroizing<[u8; SECRET_LEN]>)>,
101	    parents: BTreeMap<[u8; 16], [u8; 16]>,
102	    override_seeds: BTreeMap<[u8; 16], Zeroizing<[u8; SECRET_LEN]>>,
103	}
104	
105	impl RotationAncestry {
106	    /// Seed the walk at the rotating root: its own override seed, plus the
107	    /// parent edge for each entry of its caller-held direct-child-scope index.
108	    pub fn rooted_at(
109	        scope_id: [u8; 16],
110	        override_seed: &[u8; SECRET_LEN],
111	        child_index: &[ChildScopeRef],
112	    ) -> Self {
113	        let ancestry = Self::default();
114	        ancestry.record(scope_id, override_seed, child_index);
115	        ancestry
116	    }
117	
118	    /// Supply the **rotating root's own** ancestor node seed. Required whenever
119	    /// the rotation is anchored at an interior scope root — a revoke or
120	    /// scope-exit on a shared folder — whose record carries an ascent link the
121	    /// gate verifies against a reader-derived keypair. A vault root carries no
122	    /// ascent link and needs none.
123	    pub fn under_parent_node_seed(
124	        self,
125	        scope_id: [u8; 16],
126	        parent_node_seed: &[u8; SECRET_LEN],
127	    ) -> Self {
128	        self.inner.borrow_mut().root = Some((scope_id, Zeroizing::new(*parent_node_seed)));
129	        self
130	    }
131	
132	    fn record(
133	        &self,
134	        scope_id: [u8; 16],
135	        override_seed: &[u8; SECRET_LEN],
136	        child_index: &[ChildScopeRef],
137	    ) {
138	        let mut inner = self.inner.borrow_mut();
139	        inner
140	            .override_seeds
141	            .insert(scope_id, Zeroizing::new(*override_seed));
142	        for child in child_index {
143	            // First-seen wins, matching the walk's own dedup: a scope listed by
144	            // two parents must gate under the same one whichever order the walk
145	            // reaches it in.
146	            inner.parents.entry(child.scope_id).or_insert(scope_id);
147	        }
148	    }
149	
150	    /// `nodeSeed(parentOverrideSeed, scope_id)` — the caller-supplied seed at the
151	    /// rotating root, otherwise derived from the parent this walk already gated.
152	    fn parent_node_seed(&self, scope_id: &[u8; 16]) -> Option<Zeroizing<[u8; SECRET_LEN]>> {
153	        let inner = self.inner.borrow();
154	        if let Some((root, seed)) = &inner.root
155	            && root == scope_id
156	        {
157	            return Some(seed.clone());
158	        }
159	        let parent = inner.parents.get(scope_id)?;
160	        let parent_seed = inner.override_seeds.get(parent)?;
161	        Some(Zeroizing::new(
162	            *kdf::node_seed(parent_seed, scope_id).as_bytes(),
163	        ))
164	    }
165	}
166	
167	/// One scope root as the adoption gate authenticated it, plus the seeds the
168	/// owner recovered from its own blobs. Terminal owner of those seeds: they
169	/// zeroize when the value is dropped.
170	struct GatedScopeRoot {
171	    envelope: Envelope,
172	    section: GrantSection,
173	    read_body: ReadBody,
174	    /// The override seed recovered from this root's own owner blob — the
175	    /// ancestor seed its descendants' ascent links are derived from.
176	    read_scope_seed: Zeroizing<[u8; SECRET_LEN]>,
177	    /// `None` when the root is held keyless — no owner-write-blob, or no
178	    /// durable write-epoch floor to open it under.
179	    write_scope_seed: Option<Zeroizing<[u8; SECRET_LEN]>>,
180	}
181	
182	/// Parse a `ChildScopeRef`'s opaque `ipnsName` bytes. A name that is not a
183	/// canonical IPNS name has no verifying key to gate against, so it is a
184	/// fail-closed rejection rather than an availability stall.
185	fn scope_name(ipns_name: &[u8]) -> Result<IpnsName, ResolveFailure> {
186	    core::str::from_utf8(ipns_name)
187	        .ok()
188	        .and_then(|text| IpnsName::parse(text).ok())
189	        .ok_or(ResolveFailure::Rejected)
190	}
191	
192	/// Recover the freshly minted override seed from the re-sealed section's own
193	/// owner blob, under the AAD the envelope about to carry it will claim.
194	///
195	/// The rotation primitive is the terminal owner of the seed it minted and hands
196	/// the publisher none, so this is the only source of the seed the record must
197	/// seal under — and a section that will not reopen under the owner key the
198	/// adoption gate re-derives can therefore never be signed (release-active,
199	/// security rule 8). That failure is permanent for these bytes, so it is a
200	/// rejection rather than a retryable stall — the sweep must not re-run it.
201	fn new_override_seed(
202	    enc_secret: &X25519Secret,
203	    record: &ResealedScopeRoot,
204	) -> Result<Zeroizing<[u8; SECRET_LEN]>, ScopeRootPublishError> {
205	    let owner_blob = &record.section.owner_blob;
206	    let aad = AadContext {
207	        v: ENVELOPE_V,
208	        id: record.scope_id,
209	        scope: record.scope_id,
210	        epoch: record.read_epoch,
211	        struct_tag: STRUCT_TAG_OWNER_BLOB,
212	    };
213	    let payload = open_owner_blob(enc_secret, &owner_blob.enc, &aad, &owner_blob.ciphertext)
214	        .map_err(|_| ScopeRootPublishError::Rejected)?;
215	    Ok(Zeroizing::new(*payload.override_seed()))
216	}
217	
218	/// Carry a resolve verdict into the publish arm without laundering a
219	/// fail-closed trust violation into a retryable transport failure (rule 6).
220	fn publish_verdict(failure: ResolveFailure) -> ScopeRootPublishError {
221	    match failure {
222	        ResolveFailure::Unavailable => ScopeRootPublishError::NotPublished,
223	        ResolveFailure::Rejected | ResolveFailure::ConflictingChildLabel => {
224	            ScopeRootPublishError::Rejected
225	        }
226	    }
227	}
228	
229	/// A fresh per-seal nonce from the injected entropy seam.
230	fn nonce<E: Entropy>(entropy: &RefCell<E>) -> Result<[u8; 24], ScopeRootPublishError> {
231	    let mut nonce = [0u8; 24];
232	    entropy
233	        .borrow_mut()
234	        .fill(&mut nonce)
235	        .map_err(|_| ScopeRootPublishError::NotPublished)?;
236	    Ok(nonce)
237	}
238	
239	impl<T, H: Http, C: CredentialStore, F, Sch, E> OwnerRotationNet<'_, T, H, C, F, Sch, E>
240	where
241	    T: RecordTransport,
242	    F: FloorStore,
243	{
244	    /// Fetch the freshest verified record at `name` and run it through the
245	    /// adoption gate under `scope_id` — the caller's own trusted label, imposed
246	    /// on the gate so a record claiming another scope is a transplant it
247	    /// rejects ([`ChildIndexResolver::direct_child_index`]'s binding obligation).
248	    async fn gated_root(
249	        &self,
250	        scope_id: [u8; 16],
251	        name: &IpnsName,
252	    ) -> Result<GatedScopeRoot, ResolveFailure> {
253	        let Some((_, record_bytes)) = fanout_get_verify(self.transport, name).await else {
254	            return Err(ResolveFailure::Unavailable);
255	        };
256	        let mut adopter = RootAdopter::new(
257	            self.gateway,
258	            self.http,
259	            self.floors,
260	            self.keys.enc_secret,
261	            self.keys.identity,
262	            scope_id,
263	        );
264	        if let Some(seed) = self.ancestry.parent_node_seed(&scope_id) {
265	            adopter = adopter.under_parent_node_seed(seed);
266	        }
267	        let (candidate, outcome) =
268	            adopter
269	                .adopt_root(name, &record_bytes)
270	                .await
271	                .map_err(|error| match error {
272	                    GateError::Rejected(_) => ResolveFailure::Rejected,
273	                    GateError::Seam(_) => ResolveFailure::Unavailable,
274	                })?;
275	        let read_scope_seed = outcome.read_scope_seed.ok_or(ResolveFailure::Unavailable)?;
276	        Ok(GatedScopeRoot {
277	            envelope: candidate.envelope,
278	            section: candidate.grant_section,
279	            read_body: outcome.adopted.read_body,
280	            read_scope_seed,
281	            write_scope_seed: outcome.write_scope_seed,
282	        })
283	    }
284	
285	    /// Unseal a gated scope root's write-body under the owner's recovered write
286	    /// scope seed at the durable write-epoch floor (the AAD epoch the owner
287	    /// blob's own recovery already bound). A root held keyless has no readable
288	    /// write-body — availability, not a trust verdict.
289	    async fn write_body(
290	        &self,
291	        root: &GatedScopeRoot,
292	        scope_id: [u8; 16],
293	    ) -> Result<WriteBody, ResolveFailure> {
294	        let (Some(write_scope_seed), Some(write_epoch)) = (
295	            root.write_scope_seed.as_deref(),
296	            floor::write_epoch_floor(self.floors, &scope_id)
297	                .await
298	                .map_err(|_| ResolveFailure::Unavailable)?,
299	        ) else {
300	            return Err(ResolveFailure::Unavailable);
301	        };
302	        let write_seed = kdf::write_seed(write_scope_seed, &scope_id);
303	        let write_key = kdf::write_key(write_seed.as_bytes());
304	        let env = &root.envelope;
305	        let ctx = AadContext {
306	            v: env.v,
307	            id: env.id,
308	            scope: env.scope,
309	            epoch: write_epoch,
310	            struct_tag: STRUCT_TAG_WRITE_BODY,
311	        };
312	        // The gate authenticated this structure's detached signature; the unseal
313	        // is what proves it is *this* scope's write-body at *this* write epoch.
314	        let plaintext = Zeroizing::new(
315	            unseal(write_key.as_bytes(), &ctx, &root.section.write_body.sealed)
316	                .map_err(|_| ResolveFailure::Rejected)?,
317	        );
318	        decode_write_body(&plaintext).map_err(|_| ResolveFailure::Rejected)
319	    }
320	
321	    /// The three encode-side mirrors of gate rejects this build would itself
322	    /// make on the record about to be signed — all release-active, because a
323	    /// signed record cannot be unpublished (security rule 8):
324	    ///
325	    /// - the commitment must verify under the owner identity (gate stage 2);
326	    /// - the read epoch must not sit below the durable revocation floor (stage 5);
327	    /// - the write epoch must not sit below the durable write floor, which the
328	    ///   owner-write-blob's AAD binds — below it the root publishes write-plane
329	    ///   dead, and floors are monotonic, so it can never be rotated back.
330	    ///
331	    /// Runs **after** the publish's own gated read, whose adoption advances the
332	    /// read-epoch floor: measured before it, the floor comparison would miss a
333	    /// cut minted below the epoch that very read just adopted.
334	    async fn check_publishable(
335	        &self,
336	        record: &ResealedScopeRoot,
337	    ) -> Result<(), ScopeRootPublishError> {
338	        let section = &record.section;
339	        let signature = EcdsaSignature::from_compact(&section.commitment_sig)
340	            .ok_or(ScopeRootPublishError::Rejected)?;
341	        verify_grant_set(self.keys.identity, &section.commitment, &signature)
342	            .map_err(|_| ScopeRootPublishError::Rejected)?;
343	
344	        let floors = self.floors;
345	        let scope_id = &record.scope_id;
346	        let read_floor = floor::read_epoch_floor(floors, scope_id)
347	            .await
348	            .map_err(|_| ScopeRootPublishError::NotPublished)?
349	            .unwrap_or(0);
350	        let write_floor = floor::write_epoch_floor(floors, scope_id)
351	            .await
352	            .map_err(|_| ScopeRootPublishError::NotPublished)?
353	            .unwrap_or(0);
354	        if record.read_epoch < read_floor || record.write_epoch < write_floor {
355	            return Err(ScopeRootPublishError::Rejected);
356	        }
357	        Ok(())
358	    }
359	}
360	
361	impl<T, H: Http, C: CredentialStore, F, Sch, E> ChildIndexResolver
362	    for OwnerRotationNet<'_, T, H, C, F, Sch, E>
363	where
364	    T: RecordTransport,
365	    F: FloorStore,
366	{
367	    async fn direct_child_index(
368	        &self,
369	        child: &ChildScopeRef,
370	    ) -> Result<Vec<ChildScopeRef>, ResolveFailure> {
371	        let name = scope_name(&child.ipns_name)?;
372	        let root = self.gated_root(child.scope_id, &name).await?;
373	        let index = self
374	            .write_body(&root, child.scope_id)
375	            .await?
376	            .direct_child_scope_index;
377	        // Extend the ancestry with what this gate pass just proved, so the next
378	        // level down can derive its own ascent authority.
379	        self.ancestry
380	            .record(child.scope_id, &root.read_scope_seed, &index);
381	        Ok(index)
382	    }
383	}
384	
385	impl<T, H: Http, C: CredentialStore, F, Sch, E> ScopeRootPublisher
386	    for OwnerRotationNet<'_, T, H, C, F, Sch, E>
387	where
388	    T: RecordTransport + Clone + 'static,
389	    F: FloorStore,
390	    Sch: Scheduler + Clone + 'static,
391	    E: Entropy,
392	{
393	    async fn publish_scope_root(
394	        &self,
395	        record: &ResealedScopeRoot,
396	    ) -> Result<(), ScopeRootPublishError> {
397	        let name = scope_name(&record.ipns_name).map_err(publish_verdict)?;
398	        let override_seed = new_override_seed(self.keys.enc_secret, record)?;
399	
400	        // The read body and the envelope fields a republish preserves come from
401	        // the node's own current record, gated — the rotation carries neither.
402	        let current = self
403	            .gated_root(record.scope_id, &name)
404	            .await
405	            .map_err(publish_verdict)?;
406	        self.check_publishable(record).await?;
407	        let write_scope_seed = current
408	            .write_scope_seed
409	            .as_deref()
410	            .ok_or(ScopeRootPublishError::NotPublished)?;
411	
412	        let node_seed = kdf::node_seed(&override_seed, &record.scope_id);
413	        let read_key = Zeroizing::new(*kdf::read_key(node_seed.as_bytes()).as_bytes());
414	        let nonce = nonce(self.entropy)?;
415	        let head = author_scope_root_with_section(
416	            EnvelopeAuthoring {
417	                node_id: record.scope_id,
418	                scope_id: record.scope_id,
419	                epoch: record.read_epoch,
420	                read_key: &read_key,
421	                nonce: &nonce,
422	                body: &current.read_body,
423	                carried_unknown: current.envelope.unknown,
424	                carried_epoch_tag_unknown: current.envelope.epoch_tag_unknown,
425	            },
426	            &name,
427	            &record.section,
428	        )
429	        .map_err(|_| ScopeRootPublishError::NotPublished)?;
430	
431	        let binding = HeadBinding {
432	            node_id: record.scope_id,
