//! The production rotation seams: the owner arm of the two impure edges the
//! read-plane rotation primitives run on (blueprint/engine.md "Rotation
//! primitives", "Pointer planes"; #1014).
//!
//! [`crate::rotation`] is pure apart from a gated read of a descendant scope
//! root's own write-body index ([`ChildIndexResolver`]) and a register-first CAS
//! publish of a re-sealed scope root ([`ScopeRootPublisher`]). Both land here,
//! composed from the net plane already in place — fan-out GET plus
//! [`RootAdopter`] for the read, [`author`](super::author) plus
//! [`publish_record`] for the write. No crypto and no trust logic is added: the
//! adoption gate stays the only judge of a resolved record, and the publish
//! pipeline stays the only path to the transport.

use core::cell::RefCell;
use std::collections::BTreeMap;

use cipherbox_core::ipns::IpnsName;
use cipherbox_core::kdf;
use cipherbox_core::seal::{
    AadContext, ChildScopeRef, Envelope, GrantSection, ReadBody, STRUCT_TAG_OWNER_BLOB,
    STRUCT_TAG_WRITE_BODY, WriteBody, decode_write_body, open_owner_blob, unseal, verify_grant_set,
};
use cipherbox_core::suite::ecdsa::{EcdsaSignature, EcdsaVerifier};
use cipherbox_core::suite::secret::SECRET_LEN;
use cipherbox_core::suite::x25519::X25519Secret;
use zeroize::Zeroizing;

use super::adopter::RootAdopter;
use super::author::{ENVELOPE_V, EnvelopeAuthoring, author_scope_root_with_section};
use super::publish::PublishOutcome;
use super::record_publish::{HeadBinding, RecordPublishRequest, preflight, publish_record};
use crate::api::ApiClient;
use crate::content::Gateway;
use crate::entropy::Entropy;
use crate::gate::{GateError, floor};
use crate::net::fanout_get_verify;
use crate::profile::SyncTimingProfile;
use crate::rotation::{
    ChildIndexResolver, ResealedScopeRoot, ResolveFailure, ScopeRootPublishError,
    ScopeRootPublisher,
};
use crate::seams::{CredentialStore, FloorStore, Http, RecordTransport, Scheduler};
use crate::session::SessionIdentity;

/// The owner key material both rotation edges run under. The owner is the
/// terminal owner of its own key material, so nothing here is zeroized.
pub struct OwnerRotationKeys<'a> {
    /// Opens each scope root's owner blob — the owner's read-seed source, and
    /// the key the re-sealed section must reopen under before it is signed.
    pub enc_secret: &'a X25519Secret,
    /// The contact-anchored owner identity: the adoption gate's stage-2 anchor.
    pub identity: &'a EcdsaVerifier,
}

/// The owner-arm rotation seams over the live net plane.
pub struct OwnerRotationNet<'a, T, H: Http, C: CredentialStore, F, Sch, E> {
    /// The record-plane transport: fan-out GET for the read, CAS PUT for the
    /// publish.
    pub transport: &'a T,
    /// The API client: register-first and the head-block upload.
    pub api: &'a ApiClient<H, C>,
    /// Content read sources for the head block.
    pub gateway: &'a Gateway,
    /// The HTTP seam the content fetch rides.
    pub http: &'a H,
    /// The durable floors the adoption gate reads and advances.
    pub floors: &'a F,
    /// The scheduler the publish pipeline's background re-PUT rides.
    pub scheduler: &'a Sch,
    /// The publish pipeline's timing policy.
    pub profile: &'a SyncTimingProfile,
    /// Injected entropy — the per-seal nonce source (determinism law: engine
    /// logic never reaches for an RNG).
    pub entropy: &'a RefCell<E>,
    /// The owner material.
    pub keys: OwnerRotationKeys<'a>,
    /// The ancestor seeds every interior scope root's gated read needs.
    pub ancestry: RotationAncestry,
}

/// The `scope_id -> parent` edges and per-scope override seeds a walk needs to
/// derive each interior scope root's ancestor node seed.
///
/// Every interior scope root carries an ascent link, and the adoption gate
/// derives the expected ascent keypair from the **reader's** ancestor node seed
/// rather than from the record — no seed, no gate pass. Seeded at the rotating
/// root ([`Self::rooted_at`]) and extended as the walk gates each level: a
/// descendant's parent edge comes from the gated parent index that named it, and
/// the parent's override seed from that parent's own gate-passing owner blob, so
/// no network-supplied field ever chooses which seed a scope is read under.
#[derive(Default)]
pub struct RotationAncestry {
    inner: RefCell<Ancestry>,
}

#[derive(Default)]
struct Ancestry {
    /// The rotating root's own ancestor node seed, when it is itself an interior
    /// scope root ([`RotationAncestry::under_parent_node_seed`]).
    root: Option<([u8; 16], Zeroizing<[u8; SECRET_LEN]>)>,
    parents: BTreeMap<[u8; 16], [u8; 16]>,
    override_seeds: BTreeMap<[u8; 16], Zeroizing<[u8; SECRET_LEN]>>,
}

impl RotationAncestry {
    /// Seed the walk at the rotating root: its own override seed, plus the
    /// parent edge for each entry of its caller-held direct-child-scope index.
    pub fn rooted_at(
        scope_id: [u8; 16],
        override_seed: &[u8; SECRET_LEN],
        child_index: &[ChildScopeRef],
    ) -> Self {
        let ancestry = Self::default();
        ancestry.record(scope_id, override_seed, child_index);
        ancestry
    }

    /// Supply the **rotating root's own** ancestor node seed. Required whenever
    /// the rotation is anchored at an interior scope root — a revoke or
    /// scope-exit on a shared folder — whose record carries an ascent link the
    /// gate verifies against a reader-derived keypair. A vault root carries no
    /// ascent link and needs none.
    pub fn under_parent_node_seed(
        self,
        scope_id: [u8; 16],
        parent_node_seed: &[u8; SECRET_LEN],
    ) -> Self {
        self.inner.borrow_mut().root = Some((scope_id, Zeroizing::new(*parent_node_seed)));
        self
    }

    fn record(
        &self,
        scope_id: [u8; 16],
        override_seed: &[u8; SECRET_LEN],
        child_index: &[ChildScopeRef],
    ) {
        let mut inner = self.inner.borrow_mut();
        inner
            .override_seeds
            .insert(scope_id, Zeroizing::new(*override_seed));
        for child in child_index {
            // First-seen wins, matching the walk's own dedup: a scope listed by
            // two parents must gate under the same one whichever order the walk
            // reaches it in.
            inner.parents.entry(child.scope_id).or_insert(scope_id);
        }
    }

    /// `nodeSeed(parentOverrideSeed, scope_id)` — the caller-supplied seed at the
    /// rotating root, otherwise derived from the parent this walk already gated.
    fn parent_node_seed(&self, scope_id: &[u8; 16]) -> Option<Zeroizing<[u8; SECRET_LEN]>> {
        let inner = self.inner.borrow();
        if let Some((root, seed)) = &inner.root
            && root == scope_id
        {
            return Some(seed.clone());
        }
        let parent = inner.parents.get(scope_id)?;
        let parent_seed = inner.override_seeds.get(parent)?;
        Some(Zeroizing::new(
            *kdf::node_seed(parent_seed, scope_id).as_bytes(),
        ))
    }
}

/// One scope root as the adoption gate authenticated it, plus the seeds the
/// owner recovered from its own blobs. Terminal owner of those seeds: they
/// zeroize when the value is dropped.
struct GatedScopeRoot {
    envelope: Envelope,
    section: GrantSection,
    read_body: ReadBody,
    /// The override seed recovered from this root's own owner blob — the
    /// ancestor seed its descendants' ascent links are derived from.
    read_scope_seed: Zeroizing<[u8; SECRET_LEN]>,
    /// `None` when the root is held keyless — no owner-write-blob, or no
    /// durable write-epoch floor to open it under.
    write_scope_seed: Option<Zeroizing<[u8; SECRET_LEN]>>,
}

/// Parse a `ChildScopeRef`'s opaque `ipnsName` bytes. A name that is not a
/// canonical IPNS name has no verifying key to gate against, so it is a
/// fail-closed rejection rather than an availability stall.
fn scope_name(ipns_name: &[u8]) -> Result<IpnsName, ResolveFailure> {
    core::str::from_utf8(ipns_name)
        .ok()
        .and_then(|text| IpnsName::parse(text).ok())
        .ok_or(ResolveFailure::Rejected)
}

/// Recover the freshly minted override seed from the re-sealed section's own
/// owner blob, under the AAD the envelope about to carry it will claim.
///
/// The rotation primitive is the terminal owner of the seed it minted and hands
/// the publisher none, so this is the only source of the seed the record must
/// seal under — and a section that will not reopen under the owner key the
/// adoption gate re-derives can therefore never be signed (release-active,
/// security rule 8). That failure is permanent for these bytes, so it is a
/// rejection rather than a retryable stall — the sweep must not re-run it.
fn new_override_seed(
    enc_secret: &X25519Secret,
    record: &ResealedScopeRoot,
) -> Result<Zeroizing<[u8; SECRET_LEN]>, ScopeRootPublishError> {
    let owner_blob = &record.section.owner_blob;
    let aad = AadContext {
        v: ENVELOPE_V,
        id: record.scope_id,
        scope: record.scope_id,
        epoch: record.read_epoch,
        struct_tag: STRUCT_TAG_OWNER_BLOB,
    };
    let payload = open_owner_blob(enc_secret, &owner_blob.enc, &aad, &owner_blob.ciphertext)
        .map_err(|_| ScopeRootPublishError::Rejected)?;
    Ok(Zeroizing::new(*payload.override_seed()))
}

/// Carry a resolve verdict into the publish arm without laundering a
/// fail-closed trust violation into a retryable transport failure (rule 6).
fn publish_verdict(failure: ResolveFailure) -> ScopeRootPublishError {
    match failure {
        ResolveFailure::Unavailable => ScopeRootPublishError::NotPublished,
        ResolveFailure::Rejected | ResolveFailure::ConflictingChildLabel => {
            ScopeRootPublishError::Rejected
        }
    }
}

/// A fresh per-seal nonce from the injected entropy seam.
fn nonce<E: Entropy>(entropy: &RefCell<E>) -> Result<[u8; 24], ScopeRootPublishError> {
    let mut nonce = [0u8; 24];
    entropy
        .borrow_mut()
        .fill(&mut nonce)
        .map_err(|_| ScopeRootPublishError::NotPublished)?;
    Ok(nonce)
}

impl<T, H: Http, C: CredentialStore, F, Sch, E> OwnerRotationNet<'_, T, H, C, F, Sch, E>
where
    T: RecordTransport,
    F: FloorStore,
{
    /// Fetch the freshest verified record at `name` and run it through the
    /// adoption gate under `scope_id` — the caller's own trusted label, imposed
    /// on the gate so a record claiming another scope is a transplant it
    /// rejects ([`ChildIndexResolver::direct_child_index`]'s binding obligation).
    async fn gated_root(
        &self,
        scope_id: [u8; 16],
        name: &IpnsName,
    ) -> Result<GatedScopeRoot, ResolveFailure> {
        let Some((_, record_bytes)) = fanout_get_verify(self.transport, name).await else {
            return Err(ResolveFailure::Unavailable);
        };
        let mut adopter = RootAdopter::new(
            self.gateway,
            self.http,
            self.floors,
            self.keys.enc_secret,
            self.keys.identity,
            scope_id,
        );
        if let Some(seed) = self.ancestry.parent_node_seed(&scope_id) {
            adopter = adopter.under_parent_node_seed(seed);
        }
        let (candidate, outcome) =
            adopter
                .adopt_root(name, &record_bytes)
                .await
                .map_err(|error| match error {
                    GateError::Rejected(_) => ResolveFailure::Rejected,
                    GateError::Seam(_) => ResolveFailure::Unavailable,
                })?;
        let read_scope_seed = outcome.read_scope_seed.ok_or(ResolveFailure::Unavailable)?;
        Ok(GatedScopeRoot {
            envelope: candidate.envelope,
            section: candidate.grant_section,
            read_body: outcome.adopted.read_body,
            read_scope_seed,
            write_scope_seed: outcome.write_scope_seed,
        })
    }

    /// Unseal a gated scope root's write-body under the owner's recovered write
    /// scope seed at the durable write-epoch floor (the AAD epoch the owner
    /// blob's own recovery already bound). A root held keyless has no readable
    /// write-body — availability, not a trust verdict.
    async fn write_body(
        &self,
        root: &GatedScopeRoot,
        scope_id: [u8; 16],
    ) -> Result<WriteBody, ResolveFailure> {
        let (Some(write_scope_seed), Some(write_epoch)) = (
            root.write_scope_seed.as_deref(),
            floor::write_epoch_floor(self.floors, &scope_id)
                .await
                .map_err(|_| ResolveFailure::Unavailable)?,
        ) else {
            return Err(ResolveFailure::Unavailable);
        };
        let write_seed = kdf::write_seed(write_scope_seed, &scope_id);
        let write_key = kdf::write_key(write_seed.as_bytes());
        let env = &root.envelope;
        let ctx = AadContext {
            v: env.v,
            id: env.id,
            scope: env.scope,
            epoch: write_epoch,
            struct_tag: STRUCT_TAG_WRITE_BODY,
        };
        // The gate authenticated this structure's detached signature; the unseal
        // is what proves it is *this* scope's write-body at *this* write epoch.
        let plaintext = Zeroizing::new(
            unseal(write_key.as_bytes(), &ctx, &root.section.write_body.sealed)
                .map_err(|_| ResolveFailure::Rejected)?,
        );
        decode_write_body(&plaintext).map_err(|_| ResolveFailure::Rejected)
    }

    /// The three encode-side mirrors of gate rejects this build would itself
    /// make on the record about to be signed — all release-active, because a
    /// signed record cannot be unpublished (security rule 8):
    ///
    /// - the commitment must verify under the owner identity (gate stage 2);
    /// - the read epoch must not sit below the durable revocation floor (stage 5);
    /// - the write epoch must not sit below the durable write floor, which the
    ///   owner-write-blob's AAD binds — below it the root publishes write-plane
    ///   dead, and floors are monotonic, so it can never be rotated back.
    ///
    /// Runs **after** the publish's own gated read, whose adoption advances the
    /// read-epoch floor: measured before it, the floor comparison would miss a
    /// cut minted below the epoch that very read just adopted.
    async fn check_publishable(
        &self,
        record: &ResealedScopeRoot,
    ) -> Result<(), ScopeRootPublishError> {
        let section = &record.section;
        let signature = EcdsaSignature::from_compact(&section.commitment_sig)
            .ok_or(ScopeRootPublishError::Rejected)?;
        verify_grant_set(self.keys.identity, &section.commitment, &signature)
            .map_err(|_| ScopeRootPublishError::Rejected)?;

        let floors = self.floors;
        let scope_id = &record.scope_id;
        let read_floor = floor::read_epoch_floor(floors, scope_id)
            .await
            .map_err(|_| ScopeRootPublishError::NotPublished)?
            .unwrap_or(0);
        let write_floor = floor::write_epoch_floor(floors, scope_id)
            .await
            .map_err(|_| ScopeRootPublishError::NotPublished)?
            .unwrap_or(0);
        if record.read_epoch < read_floor || record.write_epoch < write_floor {
            return Err(ScopeRootPublishError::Rejected);
        }
        Ok(())
    }
}

impl<T, H: Http, C: CredentialStore, F, Sch, E> ChildIndexResolver
    for OwnerRotationNet<'_, T, H, C, F, Sch, E>
where
    T: RecordTransport,
    F: FloorStore,
{
    async fn direct_child_index(
        &self,
        child: &ChildScopeRef,
    ) -> Result<Vec<ChildScopeRef>, ResolveFailure> {
        let name = scope_name(&child.ipns_name)?;
        let root = self.gated_root(child.scope_id, &name).await?;
        let index = self
            .write_body(&root, child.scope_id)
            .await?
            .direct_child_scope_index;
        // Extend the ancestry with what this gate pass just proved, so the next
        // level down can derive its own ascent authority.
        self.ancestry
            .record(child.scope_id, &root.read_scope_seed, &index);
        Ok(index)
    }
}

impl<T, H: Http, C: CredentialStore, F, Sch, E> ScopeRootPublisher
    for OwnerRotationNet<'_, T, H, C, F, Sch, E>
where
    T: RecordTransport + Clone + 'static,
    F: FloorStore,
    Sch: Scheduler + Clone + 'static,
    E: Entropy,
{
    async fn publish_scope_root(
        &self,
        record: &ResealedScopeRoot,
    ) -> Result<(), ScopeRootPublishError> {
        let name = scope_name(&record.ipns_name).map_err(publish_verdict)?;
        let override_seed = new_override_seed(self.keys.enc_secret, record)?;

        // The read body and the envelope fields a republish preserves come from
        // the node's own current record, gated — the rotation carries neither.
        let current = self
            .gated_root(record.scope_id, &name)
            .await
            .map_err(publish_verdict)?;
        self.check_publishable(record).await?;
        let write_scope_seed = current
            .write_scope_seed
            .as_deref()
            .ok_or(ScopeRootPublishError::NotPublished)?;

        let node_seed = kdf::node_seed(&override_seed, &record.scope_id);
        let read_key = Zeroizing::new(*kdf::read_key(node_seed.as_bytes()).as_bytes());
        let nonce = nonce(self.entropy)?;
        let head = author_scope_root_with_section(
            EnvelopeAuthoring {
                node_id: record.scope_id,
                scope_id: record.scope_id,
                epoch: record.read_epoch,
                read_key: &read_key,
                nonce: &nonce,
                body: &current.read_body,
                carried_unknown: current.envelope.unknown,
                carried_epoch_tag_unknown: current.envelope.epoch_tag_unknown,
            },
            &name,
            &record.section,
        )
        .map_err(|_| ScopeRootPublishError::NotPublished)?;

        let binding = HeadBinding {
            node_id: record.scope_id,
            scope_id: record.scope_id,
            epoch: record.read_epoch,
        };
        let preflighted = preflight(&binding, &read_key, &head)
            .map_err(|_| ScopeRootPublishError::NotPublished)?;

        let signer = SessionIdentity::write_name_signer(write_scope_seed, &record.scope_id);
        let receipt = publish_record(
            self.transport,
            self.api,
            self.floors,
            self.scheduler,
            self.profile,
            &RecordPublishRequest {
                name: &name,
                signer: &signer,
                head: &preflighted,
                content_cids: Vec::new(),

//! The adoption gate — the six-stage trust pipeline every resolved record
//! passes before it touches the snapshot (blueprint/engine.md "Adoption gate
//! and floors"; CONTEXT.md "Adoption gate"). It composes the #33 pipeline with
//! the #39 D3 seal-auth stage and the D4 floor law. The six stages are
//! enumerated on [`GateStage`] and documented at each stage below.
//!
//! The gate is a **pure composition of `crates/core`'s verify/unseal
//! functions** plus the engine's durable floors: no crypto, no codec, and no
//! cryptographic error code of its own. Every cryptographic verdict is a core
//! [`CodecError`] surfaced verbatim through [`RejectionReason::Trust`]; the only
//! engine-domain verdicts are the two floor comparisons (stages 4 and 5), the
//! [`FloorStore`] seam's territory.
//!
//! Every failure is fail-closed and whole-record: the caller pins last-known-
//! good and never renders the rejected record. Floors advance (via
//! [`floor::advance_on_unseal`]) **only** after stage 6 succeeds — the
//! AAD-confirmed-unseal rule of the floor law.

use core::fmt;

use cipherbox_core::error::{CodecError, TrustViolation};
use cipherbox_core::ipns::{IpnsName, IpnsRecord};
use cipherbox_core::kdf;
use cipherbox_core::seal::{
    AadContext, AscentLink, Envelope, GrantSection, GrantSetCommitment, Permission,
    PreservedFields, ReadBody, STRUCT_TAG_ASCENT_LINK, STRUCT_TAG_GRANT_BLOB,
    STRUCT_TAG_HISTORY_LINK, STRUCT_TAG_OWNER_BLOB, STRUCT_TAG_OWNER_WRITE_BLOB,
    STRUCT_TAG_WRITE_BODY, StructureSigInput, open_ascent_link, open_grant_blob, open_owner_blob,
    open_read_body, verify_grant_set, verify_structure,
};
use cipherbox_core::suite::ecdsa::{EcdsaSignature, EcdsaVerifier};
use cipherbox_core::suite::ed25519::{Ed25519Signature, Ed25519Verifier};
use cipherbox_core::suite::secret::{SecretBytes, ct_eq};
use cipherbox_core::suite::x25519::X25519Secret;
use zeroize::Zeroizing;

use crate::gate::floor;
use crate::seams::{FloorStore, SeamError};

/// The six ordered stages of the adoption gate. The stage a rejection names is
/// the first stage that failed; earlier stages all passed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum GateStage {
    /// Stage 1: core's IPNS record verify chain.
    RecordVerify,
    /// Stage 2: the owner-signed grant-set commitment.
    CommitmentVerify,
    /// Stage 3: seed-bearing structure signatures under committed pseudonyms.
    GrantSection,
    /// Stage 4: strictly-newer sequence vs the durable per-name floor.
    Sequence,
    /// Stage 5: epoch tag at or above the scope's durable read-epoch floor.
    Epoch,
    /// Stage 6: HPKE seed source and symmetric read-body unseal.
    Unseal,
}

impl GateStage {
    /// Every stage, in pipeline order — the anti-vacuity anchor for the
    /// six-stage matrix.
    pub const ALL: &'static [GateStage] = &[
        GateStage::RecordVerify,
        GateStage::CommitmentVerify,
        GateStage::GrantSection,
        GateStage::Sequence,
        GateStage::Epoch,
        GateStage::Unseal,
    ];

    /// The stable kebab-case name of the stage.
    pub fn name(&self) -> &'static str {
        match self {
            GateStage::RecordVerify => "record-verify",
            GateStage::CommitmentVerify => "commitment-verify",
            GateStage::GrantSection => "grant-section",
            GateStage::Sequence => "sequence",
            GateStage::Epoch => "epoch",
            GateStage::Unseal => "unseal",
        }
    }
}

/// The engine floor-law verdict names — the two adoption-gate rejections that
/// are engine domain (a durable-floor comparison), not a composed core check.
/// Every *other* gate rejection carries a core `TrustViolation`/`Malformed`
/// check name verbatim.
pub const FLOOR_VERDICTS: &[&str] = &["sequence-not-newer", "epoch-below-floor"];

/// Why the gate rejected a record. Fail-closed in every arm: a rejection is a
/// trust violation, never mere staleness.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RejectionReason {
    /// A composed `crates/core` cryptographic/codec check fired — surfaced
    /// verbatim, never reclassified. Covers stages 1–3 and 6.
    Trust(CodecError),
    /// Stage 4: the record's sequence is not strictly newer than the durable
    /// per-name sequence floor — a replay/rollback, fail-closed.
    SequenceNotNewer {
        /// The durable per-name sequence floor.
        floor: u64,
        /// The rejected record's sequence.
        sequence: u64,
    },
    /// Stage 5: the envelope epoch tag is below the scope's durable read-epoch
    /// floor — an old-epoch record past a revocation boundary, fail-closed.
    EpochBelowFloor {
        /// The durable read-epoch floor.
        floor: u64,
        /// The rejected record's epoch tag.
        epoch: u64,
    },
}

/// A fail-closed adoption-gate rejection: the stage that fired and its reason.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GateRejection {
    /// The first stage that failed.
    pub stage: GateStage,
    /// Why it failed.
    pub reason: RejectionReason,
}

impl GateRejection {
    /// The stable named error for this rejection: the composed core check name
    /// for a cryptographic/codec stage, or the engine floor-law verdict name
    /// for a floor stage. This is the string the six-stage matrix asserts 1:1
    /// against the design tables.
    pub fn check(&self) -> &'static str {
        match &self.reason {
            RejectionReason::Trust(e) => e.check(),
            RejectionReason::SequenceNotNewer { .. } => "sequence-not-newer",
            RejectionReason::EpochBelowFloor { .. } => "epoch-below-floor",
        }
    }
}

impl fmt::Display for GateRejection {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "adoption gate rejected at stage [{}]: [{}]",
            self.stage.name(),
            self.check()
        )
    }
}

impl std::error::Error for GateRejection {}

/// The result of running the gate: a fail-closed [`GateRejection`], or a host
/// seam I/O failure — availability, never a trust decision. Only
/// [`GateError::Rejected`] means the record was untrustworthy; a
/// [`GateError::Seam`] is a retryable read of the durable floors.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum GateError {
    /// A fail-closed gate rejection.
    Rejected(GateRejection),
    /// A [`FloorStore`] seam failure — host I/O, not a trust verdict.
    Seam(SeamError),
}

impl fmt::Display for GateError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            GateError::Rejected(r) => write!(f, "{r}"),
            GateError::Seam(e) => write!(f, "{e}"),
        }
    }
}

impl std::error::Error for GateError {}

impl GateError {
    /// The rejection, if this was a fail-closed trust verdict (not a seam I/O
    /// failure). Convenience for tests and hosts that classify verdicts.
    pub fn rejection(&self) -> Option<&GateRejection> {
        match self {
            GateError::Rejected(r) => Some(r),
            GateError::Seam(_) => None,
        }
    }
}

/// The reader's HPKE seed source, opened at the unseal stage to prove the
/// reader can obtain the scope seed (`hpke-open-failed` on tamper). The public
/// `enc`/`ciphertext` are the envelope grant-section blob addressed to this
/// reader; the secret is the reader's own. A holder that already possesses the
/// scope read key passes no seed blob.
pub enum SeedBlob<'a> {
    /// The vault owner's own-scope owner blob (HPKE to the owner enc subkey).
    Owner {
        /// The owner's X25519 encryption secret.
        enc_secret: &'a X25519Secret,
        /// The HPKE encapsulated key.
        enc: [u8; 32],
        /// The HPKE ciphertext.
        ciphertext: Vec<u8>,
        /// The structured AAD the blob was sealed under.
        aad: AadContext,
    },
    /// A grantee's grant blob (HPKE to the recipient enc subkey).
    Grantee {
        /// The grantee's X25519 encryption secret.
        enc_secret: &'a X25519Secret,
        /// The HPKE encapsulated key.
        enc: [u8; 32],
        /// The HPKE ciphertext.
        ciphertext: Vec<u8>,
        /// The structured AAD the blob was sealed under.
        aad: AadContext,
    },
}

/// The hand-fed resolved record the gate adopts — the public bytes a resolve
/// would assemble off the record/content plane. This slice does not resolve;
/// tests feed candidates directly (blueprint/engine.md: "records are
/// hand-fed").
pub struct Candidate {
    /// The IPNS name the record was fetched under — the verify chain's sole
    /// trust anchor.
    pub name: IpnsName,
    /// The raw IPNS record protobuf bytes.
    pub record_bytes: Vec<u8>,
    /// The scope root's grant section — the commitment (+ its owner signature)
    /// and every seed-bearing structure with its detached structure signature.
    /// The gate enumerates its structures for stage-3 authentication **from this
    /// record's own bytes**, recomputing each `H(ciphertext)` (#687), so
    /// completeness is gate-enforced and never caller-asserted.
    pub grant_section: GrantSection,
    /// The scope root's envelope (carries the plaintext epoch tag and the
    /// sealed read-body).
    pub envelope: Envelope,
}

/// The reader's private context for adoption. The gate borrows every field and
/// zeroizes none of it — the reader is the terminal owner of its own key
/// material.
pub struct ReaderContext<'a> {
    /// The contact-code-anchored owner identity (stage-2 verification anchor).
    pub owner_identity: &'a EcdsaVerifier,
    /// The scope id (the read-epoch floor key and the AAD scope binding).
    pub scope_id: [u8; 16],
    /// The reader's own derived scope read key for the read-body unseal.
    pub read_key: &'a [u8; 32],
    /// The reader's cached ancestor node seed — the trusted secret the expected
    /// ascent keypair re-derives from. Required whenever
    /// `candidate.grant_section.ascent_link` is `Some`; a `None` here against a
    /// present ascent link is fail-closed
    /// (cannot verify).
    pub parent_node_seed: Option<&'a [u8; 32]>,
    /// The reader's HPKE seed source, opened at the unseal stage; `None` for a
    /// holder that already possesses the read key.
    pub seed_blob: Option<SeedBlob<'a>>,
}

/// A record that passed all six gate stages: the unsealed read-body and the
/// authenticated sequence/epoch the floor law advanced to.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Adopted {
    /// The unsealed, uniqueness-checked read-body.
    pub read_body: ReadBody,
    /// The authenticated record sequence (the new per-name floor).
    pub sequence: u64,
    /// The authenticated epoch tag (the new read-epoch floor).
    pub epoch: u64,
}

/// A gate pass whose floor-law advance is **deferred**: all six stages
/// succeeded and the read-body unsealed, but the durable floors have not moved
/// yet. A caller that must durably persist accepted state (the accept flow's
/// received-shares bookmark) persists first, then calls [`commit`] — so a
/// persist failure leaves the floors untouched and the record re-adopts cleanly
/// on redelivery instead of being stranded below an already-advanced sequence
/// floor. The durability of the floor advance is thus gated on the durability
/// of the accepted state.
///
/// [`commit`]: PendingAdoption::commit
#[must_use = "the deferred floor advance must be committed once the accepted state is durable"]
pub struct PendingAdoption {
    adopted: Adopted,
    scope_id: [u8; 16],
    ipns_name: Vec<u8>,
}

impl PendingAdoption {
    /// Commit the deferred floor-law advance (the AAD-confirmed-unseal rule),
    /// then yield the [`Adopted`] result. Call only after the accepted state is
    /// durably persisted.
    ///
    /// The stage-4/5 floor reads and this advance are deliberately not a CAS
    /// pair: the engine is the single writer (blueprint/engine.md "Facade"), and
    /// cross-writer contention is resolved on the publish plane, never on the
    /// local floor read.
    pub async fn commit<F: FloorStore>(self, floors: &F) -> Result<Adopted, GateError> {
        floor::advance_on_unseal(
            floors,
            &self.scope_id,
            &self.ipns_name,
            self.adopted.sequence,
            self.adopted.epoch,
        )
        .await
        .map_err(GateError::Seam)?;
        Ok(self.adopted)
    }
}

/// The committed write-capable pseudonyms of a scope root: the owner pseudonym
/// plus every write-permission entry's pseudonym. Read-only entries never
/// authorize a seed-bearing structure.
fn committed_write_pseudonyms(commitment: &GrantSetCommitment) -> Vec<Ed25519Verifier> {
    let mut set = Vec::new();
    if let Some(owner) = Ed25519Verifier::from_bytes(commitment.owner_pseudonym_pk) {
        set.push(owner);
    }
    for entry in &commitment.entries {
        if entry.permission == Permission::Write {
            if let Some(pk) = Ed25519Verifier::from_bytes(entry.pseudonym_pk) {
                set.push(pk);
            }
        }
    }
    set
}

/// Authenticate one seed-bearing structure against the committed write-capable
/// pseudonyms, recomputing the signed input **from the record's actual sealed
/// bytes** (#687): the `ciphertext_hash` is `H(ciphertext)` over `ciphertext`,
/// and `scope`/`epoch` come from the authenticated envelope — never a
/// caller-supplied [`StructureSigInput`]. A signature therefore proves "the
/// committed writer signed *these* bytes at *this* scope/epoch", not merely "the
/// writer once signed some hash". The structure is trusted iff the recomputed
/// input verifies under at least one committed pseudonym; otherwise the whole
/// record is a `structure-signature-invalid` trust violation.
fn authenticate_structure(
    committed: &[Ed25519Verifier],
    scope: [u8; 16],
    epoch: u64,
    struct_tag: u8,
    recipient_tag: Option<[u8; 32]>,
    ciphertext: &[u8],
    signature: &[u8; 64],
) -> Result<(), CodecError> {
    let input =
        StructureSigInput::over_ciphertext(scope, epoch, struct_tag, recipient_tag, ciphertext);
    let sig = Ed25519Signature::from_bytes(*signature);
    for pseudonym in committed {
        if verify_structure(pseudonym, &input, &sig).is_ok() {
            return Ok(());
        }
    }
    Err(TrustViolation::StructureSignatureInvalid.into())
}

/// The gate's stage-3 predicate: authenticate every structure signature
/// `section` carries against the pseudonyms its own commitment names,
/// recomputed at `envelope`'s scope and epoch — whatever epoch a structure's own
/// sealed AAD binds (blueprint/core.md "Structure signatures").
///
/// Also run release-active on the produce side (`net/author.rs`), so a scope
/// root this build's own gate would reject is never signed (AGENTS.md rule 8).
pub fn authenticate_section_structures(
    section: &GrantSection,
    envelope: &Envelope,
) -> Result<(), CodecError> {
    let (scope, epoch) = (envelope.scope, envelope.epoch);
    let committed = committed_write_pseudonyms(&section.commitment);
    let authenticate = |tag: u8, recipient: Option<[u8; 32]>, ct: &[u8], sig: &[u8; 64]| {
        authenticate_structure(&committed, scope, epoch, tag, recipient, ct, sig)
    };
    authenticate(
        STRUCT_TAG_OWNER_BLOB,
        None,
        &section.owner_blob.ciphertext,
        &section.owner_blob.signature,
    )?;
    if let Some(owner_write) = &section.owner_write_blob {
        authenticate(
            STRUCT_TAG_OWNER_WRITE_BLOB,
            None,
            &owner_write.ciphertext,
            &owner_write.signature,
        )?;
    }
    for blob in &section.grant_blobs {
        authenticate(
            STRUCT_TAG_GRANT_BLOB,
            Some(blob.tag),
            &blob.ciphertext,
            &blob.signature,
        )?;
    }
    for link in &section.history_links {
        authenticate(STRUCT_TAG_HISTORY_LINK, None, &link.sealed, &link.signature)?;
    }
    authenticate(
        STRUCT_TAG_WRITE_BODY,
        None,
        &section.write_body.sealed,
        &section.write_body.signature,
    )?;
    if let Some(ascent) = &section.ascent_link {
        authenticate(
            STRUCT_TAG_ASCENT_LINK,
            None,
            &ascent.ciphertext,
            &ascent.signature,
        )?;
    }
    Ok(())
}

impl SeedBlob<'_> {
    /// The structured AAD the blob claims to be sealed under — cross-checked
    /// against the envelope before it is trusted.
    fn aad(&self) -> &AadContext {
        match self {
            SeedBlob::Owner { aad, .. } | SeedBlob::Grantee { aad, .. } => aad,
        }
    }

    /// The domain-separation tag this blob variant must carry — the AAD's
    /// `structTag` is pinned to it so an owner blob can never present as a grant
    /// blob (or any other structure).
    fn struct_tag(&self) -> u8 {
        match self {
            SeedBlob::Owner { .. } => STRUCT_TAG_OWNER_BLOB,
            SeedBlob::Grantee { .. } => STRUCT_TAG_GRANT_BLOB,
        }
    }
}

/// The two seeds a seed blob yields: the recovered read scope seed (always) and,
/// for a write-grantee, the scope write seed the held set derives its renewal
/// signer from (`None` for a read-only grant and the owner arm). Both zeroize on
/// drop.
type UnsealedSeeds = (SecretBytes, Option<Zeroizing<[u8; 32]>>);

/// Open the reader's HPKE seed source, returning the recovered read scope seed
/// (for the gate's read-key cross-check) and, for a write-grantee, the write
/// scope seed. The write seed is consumed by the resolve/gate driver that keeps
/// a write-capable scope alive (blueprint/engine.md "Liveness").
fn open_seed_blob(blob: &SeedBlob<'_>) -> Result<UnsealedSeeds, CodecError> {
    match blob {
        SeedBlob::Owner {
            enc_secret,
            enc,
            ciphertext,
            aad,
        } => {
            let payload = open_owner_blob(enc_secret, enc, aad, ciphertext)?;
            Ok((SecretBytes::new(*payload.override_seed()), None))
        }
        SeedBlob::Grantee {
            enc_secret,
            enc,
            ciphertext,
            aad,
        } => {
            let payload = open_grant_blob(enc_secret, enc, aad, ciphertext)?;
            let write_scope_seed = payload.write_scope_seed().copied().map(Zeroizing::new);
            Ok((
                SecretBytes::new(*payload.read_scope_seed()),
                write_scope_seed,
            ))
        }
    }
}

/// Run the adoption gate over one hand-fed [`Candidate`] for one
/// [`ReaderContext`], **deferring** the floor-law advance. On success all six
/// stages passed and the read-body unsealed, but the durable floors have not
/// moved: the caller persists any accepted state, then calls
/// [`PendingAdoption::commit`] to advance them. On failure nothing durable
/// changed and the caller pins last-known-good. Use [`adopt`] for the eager
/// path that has no accepted state to persist first.
pub async fn adopt_deferred<F: FloorStore>(
    floors: &F,
    reader: &ReaderContext<'_>,
    candidate: &Candidate,
) -> Result<(PendingAdoption, Option<Zeroizing<[u8; 32]>>), GateError> {
    // Stage 1 — record verify (Ed25519 key from the name itself).
    let verified = IpnsRecord::unmarshal(&candidate.record_bytes)
        .and_then(|record| record.verify(&candidate.name))
        .map_err(|e| reject(GateStage::RecordVerify, RejectionReason::Trust(e)))?;

    // Stage 2 — commitment verify against the contact-anchored owner identity,
    // and its binding to this record's name (the name is inside the signed
    // commitment preimage; a commitment for a different scope root is invalid
    // here).
    let section = &candidate.grant_section;
    let commitment_sig =
        EcdsaSignature::from_compact(&section.commitment_sig).ok_or_else(|| {
            reject(
                GateStage::CommitmentVerify,
                RejectionReason::Trust(TrustViolation::CommitmentInvalid.into()),
            )
        })?;
    verify_grant_set(reader.owner_identity, &section.commitment, &commitment_sig)
        .map_err(|e| reject(GateStage::CommitmentVerify, RejectionReason::Trust(e)))?;
    if section.commitment.ipns_name != candidate.name.as_str().as_bytes() {
        return Err(reject(
            GateStage::CommitmentVerify,
            RejectionReason::Trust(TrustViolation::CommitmentInvalid.into()),
        ));
    }

    // Stage 3 — grant-section authentication under `authenticate_structure`'s
    // recompute contract (#687). Any failure rejects the whole record (#39 D3).
    let epoch = candidate.envelope.epoch;
    authenticate_section_structures(section, &candidate.envelope)
        .map_err(|e| reject(GateStage::GrantSection, RejectionReason::Trust(e)))?;
    if let Some(ascent) = &section.ascent_link {
        // The ascent link is doubly checked: its structure signature (above)
        // proves the committed writer authored it, and this derive-and-verify
        // proves the sealed seed is *this* scope root's.
        //
        // Ascent authority is reader-derived: the expected keypair comes from the
        // reader's cached ancestor node seed, never the network-supplied record
        // (blueprint/engine.md: "Ancestor readers derive the expected ascent
        // keypair from the parent node seed"). No reader seed ⇒ cannot verify ⇒
        // fail closed. The AAD is rebuilt from the authenticated envelope, so a
        // link sealed under a foreign context fails the HPKE tag on open.
        let parent_node_seed = reader.parent_node_seed.ok_or_else(|| {
            reject(
                GateStage::GrantSection,
                RejectionReason::Trust(TrustViolation::AscentLinkMismatch.into()),
            )
        })?;
        let aad = AadContext {
            v: candidate.envelope.v,
            id: candidate.envelope.id,
            scope: candidate.envelope.scope,
            epoch: candidate.envelope.epoch,
            struct_tag: STRUCT_TAG_ASCENT_LINK,
        };
        let link = AscentLink {
            ascent_public: ascent.ascent_public,
            enc: ascent.enc,
            ciphertext: ascent.ciphertext.clone(),
            unknown: PreservedFields::new(),
        };
        // Cross-check the recovered override seed: the ascent public key is
        // published, so anyone can seal a rogue payload to it. The seed the link
        // carries is this scope root's current override seed (CONTEXT.md "Ascent
        // link"/"Override seed"), so it must belong to this epoch and derive this
        // node's read key — the ascent-link half of engine.md:406-408.
        let payload = open_ascent_link(parent_node_seed, &aad, &link)
            .map_err(|e| reject(GateStage::GrantSection, RejectionReason::Trust(e)))?;
        let node_seed = kdf::node_seed(payload.override_seed(), &candidate.envelope.id);
        let derived_read_key = kdf::read_key(node_seed.as_bytes());
        if payload.epoch != candidate.envelope.epoch
            || !ct_eq(derived_read_key.as_bytes(), reader.read_key)
        {
            return Err(reject(
                GateStage::GrantSection,
                RejectionReason::Trust(TrustViolation::AscentLinkMismatch.into()),
            ));
        }
    }

    // Stages 4/5 — the durable floor law ([`floor::check`]): strictly-newer
    // sequence vs the per-name floor, epoch tag at or above the scope's
    // read-epoch floor.
    let name_bytes = candidate.name.as_str().as_bytes();
    floor::check(
        floors,
        name_bytes,
        &reader.scope_id,
        verified.sequence,
        epoch,
        floor::Strictness::StrictlyNewer,
    )
    .await?;

    // Stage 6 — unseal success required (AAD-confirmed). The HPKE seed source
    // (if any) opens first, then the symmetric read-body; the read-body decode
    // enforces child id/ipnsName uniqueness fail-closed.
    //
    // Reader-scope precondition: the scope UUID is not in the read-key KDF, so a
    // read body sealed under a foreign scope still opens under this reader's key.
    // Bind the envelope's scope to the reader's own scope so it joins the same
    // equivalence class as every AAD/structure scope — a foreign-scope envelope
    // is a scope transplant, fail-closed (blueprint/engine.md cross-check).
    if candidate.envelope.scope != reader.scope_id {
        return Err(reject(
            GateStage::Unseal,
            RejectionReason::Trust(TrustViolation::SealOpenFailed.into()),
        ));
    }
    // A write-grantee's blob also carries the scope write seed the held set
    // derives its per-name renewal signer from; `None` for a read-only grant,
    // the owner arm, or a holder that passes no seed blob.
    let mut write_scope_seed = None;
    if let Some(blob) = &reader.seed_blob {
        // Bind the blob to THIS envelope: a seed blob sealed under a different
        // scope/epoch/version is a transplant, not this record's seed source.
        // Fail closed before opening (blueprint/engine.md cross-check discipline).
        let aad = blob.aad();
        if aad.scope != reader.scope_id
            || aad.id != candidate.envelope.id
            || aad.epoch != candidate.envelope.epoch
            || aad.v != candidate.envelope.v
            || aad.struct_tag != blob.struct_tag()
        {
            return Err(reject(
                GateStage::Unseal,
                RejectionReason::Trust(TrustViolation::HpkeOpenFailed.into()),
            ));
        }
        // Cross-check: the recovered seed must derive the reader's read key, or
        // the blob-seed and the actual-unseal key disagree — an attributable
        // abuse event (blueprint/engine.md), never a silent staleness.
        let (seed, ws) = open_seed_blob(blob)
            .map_err(|e| reject(GateStage::Unseal, RejectionReason::Trust(e)))?;
        let node_seed = kdf::node_seed(seed.as_bytes(), &candidate.envelope.id);
        let derived_read_key = kdf::read_key(node_seed.as_bytes());
        if !ct_eq(derived_read_key.as_bytes(), reader.read_key) {
            return Err(reject(
                GateStage::Unseal,
                RejectionReason::Trust(TrustViolation::SealOpenFailed.into()),
            ));
        }
        write_scope_seed = ws;
    }
    let read_body = open_read_body(&candidate.envelope, reader.read_key)
        .map_err(|e| reject(GateStage::Unseal, RejectionReason::Trust(e)))?;

    // All six stages passed; the floor-law advance is DEFERRED to
    // [`PendingAdoption::commit`] (see that type's contract).
    Ok((
        PendingAdoption {
            adopted: Adopted {
                read_body,
                sequence: verified.sequence,
                epoch,
            },
            scope_id: reader.scope_id,
            ipns_name: name_bytes.to_vec(),
        },
        write_scope_seed,
    ))
}

/// Run the adoption gate and, on success, immediately advance the floor law
/// (the AAD-confirmed-unseal rule). The eager path for callers that hold no
/// accepted state to persist first (e.g. a plain resolve); a caller that must
/// make the floor advance atomic with a durable write uses [`adopt_deferred`]
/// plus [`PendingAdoption::commit`]. Returns the adopted state and, for a
/// write-grantee, the transient scope write seed the held set derives its
/// renewal signer from (`None` for a read-only holder and the owner arm).
pub async fn adopt<F: FloorStore>(
    floors: &F,
    reader: &ReaderContext<'_>,
    candidate: &Candidate,
) -> Result<(Adopted, Option<Zeroizing<[u8; 32]>>), GateError> {
    let (pending, write_scope_seed) = adopt_deferred(floors, reader, candidate).await?;
    let adopted = pending.commit(floors).await?;
    Ok((adopted, write_scope_seed))
}

/// Build a `GateError::Rejected` from a stage and reason.
fn reject(stage: GateStage, reason: RejectionReason) -> GateError {
    GateError::Rejected(GateRejection { stage, reason })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn stage_names_are_stable_and_complete() {
        assert_eq!(GateStage::ALL.len(), 6, "the gate has exactly six stages");
        let names: Vec<&str> = GateStage::ALL.iter().map(GateStage::name).collect();
        assert_eq!(
            names,
            [
                "record-verify",
                "commitment-verify",
                "grant-section",
                "sequence",
                "epoch",
                "unseal"
            ]
        );
    }

    #[test]
    fn rejection_check_names_the_error() {
        let seq = GateRejection {
            stage: GateStage::Sequence,
            reason: RejectionReason::SequenceNotNewer {
                floor: 5,
                sequence: 3,
            },
        };
        assert_eq!(seq.check(), "sequence-not-newer");

        let epoch = GateRejection {
            stage: GateStage::Epoch,
            reason: RejectionReason::EpochBelowFloor { floor: 4, epoch: 2 },
        };
        assert_eq!(epoch.check(), "epoch-below-floor");

        let trust = GateRejection {
            stage: GateStage::RecordVerify,
            reason: RejectionReason::Trust(TrustViolation::IpnsSignatureInvalid.into()),
        };
        assert_eq!(trust.check(), "ipns-signature-invalid");
    }

    #[test]
    fn floor_verdicts_are_the_two_engine_domain_names() {
        assert_eq!(FLOOR_VERDICTS, &["sequence-not-newer", "epoch-below-floor"]);
    }
}

