    use cipherbox_core::seal::{PreservedFields, sign_grant_set};
    use std::cell::RefCell;
    use std::collections::{HashMap, HashSet};
    use std::rc::Rc;

    const SCOPE: [u8; 16] = [0x5c; 16];

